INSERT INTO "guide_rag"."rag_knowledge_units" ("unit_id", "release_id", "source_version_id", "source_id", "ordinal", "heading_path", "unit_type", "content_text", "content_digest", "token_count", "embedding_profile", "embedding") VALUES ('a61e84de-431a-4080-98dc-a639f2c8bc9e', 'rel-20261019094619-b6897071-f79d33', 'da7a589c-b80e-41d7-9fe7-11a8d8fe7d38', 'privacy-notice', 1, 'ZoikoStream Privacy Policy > What ZoikoStream collects', 'legal', 'When you create an account, ZoikoStream stores your name, email address and password. The password is hashed and is never readable by ZoikoStream or by anyone with database access. If you join an organization, ZoikoStream records your role in it.

When you attend or host an event, ZoikoStream processes the live audio and video of that event to deliver it to its audience. Live media is carried by ZoikoStream''s streaming provider for the duration of the event; it is not stored by the app on your device. Recordings exist only where an event''s organizer explicitly creates one, under the retention rules that organizer configures.

When you contact support or report a security issue, ZoikoStream keeps the message you sent so it can respond.', '\x2fcdd91d8316f239de86c38be469acd9ce034a0cd77d6fbefb98d449954a37d5', 164, 'fastembed:BAAI/bge-small-en-v1.5', '[0.019335061,0.021080587,-0.045974478,-0.05480953,-0.008566506,-0.013843367,0.058971938,-0.0030194249,-0.04965351,0.03907294,-0.009123732,0.048955303,0.048337653,-0.011312353,-0.07470853,-0.022369592,0.019415624,-0.035904136,-0.101885036,0.05349367,0.015844008,-0.103818536,0.055534594,-0.046618983,0.00042736024,0.022356166,-0.004981464,0.021456547,-0.0006386277,-0.12395923,-0.031607453,-0.10773926,-0.0042933235,-0.022624707,-0.017294139,-0.02283954,-0.01266178,-0.0021936568,-0.041973196,0.05196298,0.034641985,0.030452723,-0.006669925,-0.028008984,0.045437396,-0.06026094,0.047585733,-0.04111386,-0.03789135,0.023108084,0.012601358,0.063000076,0.009640677,0.06036836,-0.05405761,0.00024000987,0.056447636,-0.010385882,-0.018717414,-0.012171689,-0.014984673,-0.06385941,-0.098877355,0.06874689,-0.074815944,0.06246299,-0.027243638,-0.02765988,-0.013742664,-0.029593386,-0.03689774,0.0068746884,-0.058273725,-0.009721239,-0.020892609,-0.039046083,0.07025072,0.028841468,-0.07121748,0.023510898,-0.027767297,-0.024893891,0.012943749,-0.0067806984,0.01709273,0.00545477,0.058971938,-0.02289325,-0.003079847,0.004175836,-0.060529485,-0.0042966804,0.042751968,0.031929705,-0.0015088733,0.012695348,-0.03195656,0.06557808,-0.025484685,0.3493201,0.004941182,0.062248155,-0.01032546,-0.0074721957,0.048176527,-0.042725116,-0.008029422,0.0009281501,-0.012487227,0.047532026,0.01938877,-0.08045534,0.019375343,-0.011345921,0.071647145,0.046511564,0.0057501667,0.09382876,-0.022826115,-0.008076416,0.030157326,-0.0040314947,0.06735046,0.06208703,0.064235374,0.034239173,0.0555883,0.11805129,-0.029512823,-0.011345921,0.041892633,-0.034373444,-0.070411846,0.022208467,0.012413378,0.0372737,-0.015817154,-0.018516006,-0.0051560164,0.010432877,-0.004917685,0.038804393,0.064718746,-0.0