INSERT INTO "guide_rag"."rag_knowledge_units" ("unit_id", "release_id", "source_version_id", "source_id", "ordinal", "heading_path", "unit_type", "content_text", "content_digest", "token_count", "embedding_profile", "embedding") VALUES ('3bb9b0d4-1018-4b71-9129-26dd0dd9fb5b', 'rel-20261019094619-b6897071-f79d33', 'e5e147b5-3a9f-4e1d-b09f-09ca5265ff5d', 'status-page', 3, 'ZoikoStream Status Page > Subscribing to status updates', 'procedure', 'Status email contains incident and maintenance notices for the parts of the platform you care about, and nothing else. It is not a marketing list.

1. Go to /status and select "Get notified" (or scroll to "Subscribe to status updates").
2. Enter your email address.
3. Optionally choose components and regions. Select none to be notified about everything.
4. Select "Subscribe".
5. Check your inbox and open the confirmation link. Nothing else is sent until you confirm the address.

