INSERT INTO "guide_rag"."rag_knowledge_units" ("unit_id", "release_id", "source_version_id", "source_id", "ordinal", "heading_path", "unit_type", "content_text", "content_digest", "token_count", "embedding_profile", "embedding") VALUES ('eb845149-3fe4-44de-a4ed-cb48b764daae', 'rel-20261019094619-b6897071-f79d33', 'b0dbea8b-ff89-4f87-808d-c18bc89ef3fe', 'trust-security', 1, 'ZoikoStream Trust Center > Security advisories', 'prose', 'The Trust Center lists open advisories and closed advisories. If there are none open, it shows "No open security advisories."

Each advisory can show a summary and fields such as: What this means for you, Affected versions, Scope, CVSS vector, Immediate mitigation, Workaround, Fixed version, Remediation steps, and Deadline. If no workaround exists, it says "No workaround is available." If no deadline is set, it says "No deadline has been set for this advisory."

When an advisory has remediation steps:

- If the action is mandatory, it says: "Required action: apply this update as soon as you are able."
- Otherwise it says: "Recommended: apply this update during your normal change process."

Every published version of an advisory stays readable through "Show published history", and a version that was later corrected is labeled "Later updated".', '\xb9d83b2d753aaeb70aa24ca8f0ff691c6f18fe8d0e7154061e61d0b47ea40138', 180, 'fastembed:BAAI/bge-small-en-v1.5', '[0.0021333483,-0.032348286,-0.016067559,-0.009752449,0.035332642,-0.04060856,0.0021450059,0.030616295,-0.07738008,-0.0017319923,0.07690046,0.006604886,-0.03306773,0.0069346307,-0.034826368,-0.046337456,-0.0046464023,-0.007773981,-0.002564681,0.047536526,0.03146897,-0.042926762,0.03240158,0.031149216,0.019225115,0.045191675,0.031735428,-0.04639075,-0.06485645,-0.17756918,-0.059314076,-0.051266972,-0.07141137,0.0047230097,0.010898229,-0.013496217,-0.009219528,0.07588791,-0.002176648,0.007134476,0.042313904,0.050760698,-0.04988138,-0.028058276,-0.029657038,-0.0678941,0.0130032655,-0.019931234,-0.00878653,-0.035918854,0.04361956,-0.036185317,0.025393672,0.057288975,-0.0003946944,-0.0021083676,0.009512635,0.031628843,-0.044392295,0.007161122,0.020997075,-0.048549075,-0.18460374,0.04529826,0.0005741388,0.006581571,-0.017066786,-0.05049424,0.002631296,-0.032241702,0.020677324,0.017200015,-0.048442494,0.03261475,-0.03610538,0.009659188,0.01757306,0.0105318455,0.03192195,0.018665548,-0.0023598396,0.010538507,0.004836255,-0.024887398,0.014015814,0.052013062,0.038743336,0.021996303,0.04529826,-0.0095259575,0.02997679,-0.029150764,0.09214199,-0.012203884,-0.06075296,-0.040315453,-0.01991791,0.039889116,-0.09336771,0.3792264,-0.041434586,0.032747976,-0.04993467,0.041887566,0.07151796,0.0022415977,0.00653494,-0.01690691,0.02524712,0.015867714,0.011571041,-0.021529997,0.11916107,-0.038210414,0.024141308,0.042367198,0.06176551,0.0022432632,0.018292503,-0.0044998494,0.03850352,0.002388151,0.042527072,0.014322244,-0.041701045,0.027338833,0.024421092,0.0712515,-0.007787304,0.005822159,-0.016387312,-0.0055157295,-0.05611655,-0.0065849014,0.042367198,0.08921093,0.0033174313,0.007081184,-0.026672682,-0.04255372,-0.0487356,0