INSERT INTO "guide_rag"."rag_knowledge_units" ("unit_id", "release_id", "source_version_id", "source_id", "ordinal", "heading_path", "unit_type", "content_text", "content_digest", "token_count", "embedding_profile", "embedding") VALUES ('3d58531d-0302-42ec-95c0-297d6b842bbf', 'rel-20261019094619-b6897071-f79d33', 'b0dbea8b-ff89-4f87-808d-c18bc89ef3fe', 'trust-security', 3, 'ZoikoStream Trust Center > Requesting trust documentation', 'procedure', 'Confidential documents are released under an approved request. Approved access is issued to one address, for one document, purpose and scope, and it expires, so request it for the address that will actually read it. Each listed document is marked either "Request required" or "Public". If no documents are published, the page says "No documents are published yet."

To request a document:

1. Go to /trust and select "Request documents" (or scroll to "Request trust documentation").
2. Select a document, then a purpose and a scope. Only the purposes and scopes that document allows are offered.
3. Enter your email. Optionally enter your company and what you are reviewing.
4. Select "Submit request".

After you submit, the page shows your request reference. ZoikoStream reviews requests individually and will email you when a decision has been made. Nothing is released automatically.', '\xe9fa51dd82415308d4854c60f317a2a9def410bb2e5dfc2ac65790dc66ed6dd4', 186, 'fastembed:BAAI/bge-small-en-v1.5', '[-0.0111726215,0.0036021385,-0.02661987,-0.0181372,-0.022997757,-0.013902524,-0.022877907,0.0037386336,-0.099608116,0.004830594,0.011505537,0.029110072,-0.019042728,-0.0034556559,-0.01625956,-0.0015513831,-0.007843473,-0.056302555,-0.025234945,0.07739604,0.058113612,-0.057367884,0.03385078,0.029243238,0.007883423,0.01270403,-0.019082678,-0.068021156,-0.06642317,-0.17482023,-0.04154777,-0.035075907,-0.042186968,-0.018297,0.016099762,-0.030681431,-0.034223646,0.03526234,-0.010806415,0.016366092,0.063120656,0.058273412,-0.032971885,-0.006551764,0.010366968,-0.029536204,0.0057993764,-0.05475783,0.012191341,0.008149755,-0.004507667,0.007111061,-0.009221741,0.026366854,-0.04042918,0.003310838,0.071110606,0.033983946,-0.021253282,0.020667354,-0.00836282,-0.016712325,-0.13678804,0.05374577,-0.01633946,0.043998025,-0.08123122,-0.05281361,-0.031613592,-0.024449265,0.0422935,-0.0021123446,-0.06977895,0.046261843,-0.008316212,-0.02211886,0.030734697,0.035475403,0.03166686,-0.0041680937,-0.09199103,0.038964354,0.009308299,-0.01520755,-0.028897008,0.035129175,0.05238748,-0.01930906,0.043491993,-0.008436061,0.059551805,-0.047327172,0.046261843,0.039097518,-0.06269452,-0.05715482,-0.050203558,0.029323138,-0.04447742,0.40311992,-0.008955409,0.008103147,-0.046102047,-0.029269872,0.012417723,-0.0049271397,0.04636838,-0.011066089,0.017338205,-0.015580414,-0.002486874,-0.055183962,0.023716852,0.022491725,-0.014861318,0.055503562,0.029562837,0.054704566,-0.0027365598,-0.05390557,0.037046764,-0.00071659917,0.051375415,0.05907241,-0.021359816,-0.015021117,0.078514636,0.07334779,0.040056314,0.04330556,0.022744741,0.010420234,-0.08948751,-0.022105545,0.026779668,0.037659325,-0.024595749,-0.017284937