INSERT INTO "guide_rag"."rag_knowledge_units" ("unit_id", "release_id", "source_version_id", "source_id", "ordinal", "heading_path", "unit_type", "content_text", "content_digest", "token_count", "embedding_profile", "embedding") VALUES ('e7050d77-9ef9-48b6-80e1-577c5f5b9b1f', 'rel-20261019094619-b6897071-f79d33', 'b0dbea8b-ff89-4f87-808d-c18bc89ef3fe', 'trust-security', 4, 'ZoikoStream Trust Center > Reporting a security issue', 'procedure', 'Reports go to ZoikoStream''s security team, not to general support. ZoikoStream will confirm receipt and tell you what it finds.

The Trust Center states its program terms:

- Paid bounty: No
- Public credit: Not offered
- Coordinated disclosure policy: None published. ZoikoStream will agree timing with you directly.

Do not send credentials. ZoikoStream never needs a password, API key or private key to reproduce an issue, and a report containing one will be rejected rather than stored.

To report an issue:

1. Go to /trust and select "Report an issue" (or scroll to "Report a security issue").
2. Enter your email. Your name is optional.
3. Enter a one-line summary of the issue and select a category.
4. Optionally name the affected service.
5. Describe what happens, what you expected, and why it matters. Optionally add steps to reproduce.
6. Select "Submit report".

After you submit, the page shows your report reference, and ZoikoStream emails you a private link to follow it. Keep that link: it is the only way to check status without an account. The link is also shown once on the page in case the email does not arrive.', '\x007e87f2e3fd1868f387939f86042fb37c1cb356472019346ab516847f7063bd', 257, 'fastembed:BAAI/bge-small-en-v1.5', '[-0.00348764,-0.012726709,-0.08865227,-0.042533826,-0.021200037,-0.028650144,0.053448167,0.027366104,-0.095821485,0.02180193,0.052993402,0.015889995,0.024557266,0.0046011433,-0.061740924,-0.03817344,0.0078112436,-0.003918997,-0.00986437,0.061366413,-0.007710928,-0.08865227,0.026510077,-0.0076507386,0.021775179,0.03044245,-0.027553359,-0.016746022,-0.06987318,-0.18083563,-0.07634688,-0.070782706,-0.0052598827,-0.026911339,-0.014806586,-0.034107313,-0.017762555,0.007323041,-0.016398262,-0.03814669,0.04577068,0.045396164,-0.044165626,-0.005019125,0.016130753,-0.045369416,0.02034401,-0.017909683,0.046091687,-0.011268789,0.019126847,-0.014873464,-0.011663363,0.07661439,-0.03651489,0.0054972963,0.051094092,-0.00481515,-0.019541485,-0.016010374,-0.024436887,-0.048552763,-0.12476589,0.04935529,0.015488733,0.06773311,0.0060490323,-0.012071314,0.0020063126,0.002661708,0.011175161,-0.01671927,-0.086940214,0.032636017,-0.0025145784,-0.022229943,0.046198692,0.05489271,0.00015559372,0.0046245507,-0.06655607,0.015488733,0.009329353,0.008821088,-0.015301477,0.0067612734,0.0576748,0.026135566,0.04269433,-0.011308915,0.07602587,0.0039624674,0.02851639,0.019140221,-0.021828681,-0.00031244138,-0.07468833,0.011161786,-0.09903159,0.3781498,0.007135785,0.052806146,-0.026724083,0.010566579,0.076079376,-0.05478571,0.027018342,-0.016679145,0.022524202,0.012599643,0.026403073,-0.030362196,0.072013244,-0.047669988,0.02454389,0.04970305,0.047616486,0.05842382,-0.0128805265,-0.007523672,0.035765864,-0.0069485293,0.04997056,0.040500764,0.030201692,0.012760148,0.035658862,0.121662796,-0.022992343,0.037638422,0.0016008703,-0.01813706