INSERT INTO "guide_rag"."rag_knowledge_units" ("unit_id", "release_id", "source_version_id", "source_id", "ordinal", "heading_path", "unit_type", "content_text", "content_digest", "token_count", "embedding_profile", "embedding") VALUES ('5651b7f4-d9e8-4f26-a656-b08e9cdb5528', 'rel-20261019094619-b6897071-f79d33', '58a60d3d-9d4a-464d-b14d-31728d6af3bf', 'viewer-playback-help', 7, 'Viewer Help - Watching and Taking Part > Chat, Q&A and polls', 'prose', 'Depending on what the host enables, the event page can include Chat, Q&A and Polls tabs. To take part, enter your name and email when asked:

- "Enter your name and email to join the chat."
- "Enter your name and email to ask a question."
- "Enter your name and email to vote in polls."

In Q&A you can ask a question and upvote questions. Answered questions are marked as answered by the host.

If the host turns on slow mode, chat messages are limited to one every set number of seconds. Slow mode is set by the host.', '\x60a30fad7439d50781d95f7b9e6f02ca9d08b4382f7cf3eb9267d90d919f276d', 133, 'fastembed:BAAI/bge-small-en-v1.5', '[-0.018509014,0.049428385,-0.022969818,-0.03086611,0.04442163,0.0770188,0.04375584,-0.053689454,-0.0034887493,0.012150701,-0.05046702,0.017310588,0.044022158,0.0071173147,0.0566722,0.0104063265,-0.017390482,-0.03893551,-0.04407542,0.04724459,-0.042397626,-0.012164017,-0.0009637337,0.002887872,0.026152303,-0.013349126,-0.01637848,-0.05981474,-0.05603304,-0.13933691,0.051479027,-0.02735073,0.0064914706,0.013462311,-0.02753715,-0.04053341,0.01049288,-0.039627932,-0.041465517,0.011178645,0.038136557,-0.011345093,-0.020319967,-0.077924274,0.0040480145,-0.039255086,0.04197152,-0.0035719732,0.029401368,0.023622295,0.00636497,0.008875005,0.033209696,-0.024807405,-0.0009745528,0.020253388,0.018975068,0.025925934,0.0020556324,0.026152303,0.020226756,0.02210429,-0.13358447,0.12058822,-0.0315319,0.035473388,-0.042743836,0.06615308,-0.084369145,0.023049714,-0.067750975,0.0054295324,-0.014607473,0.018602224,-0.011871069,-0.028655682,-0.018948436,0.0013424028,0.049561545,-0.0032607156,-0.05811031,0.04564669,-0.016498322,-0.002485068,0.055926517,0.009241191,0.047191326,0.026525147,-0.031744957,0.05344977,-0.020639548,-0.047377747,-0.0059188893,0.055127565,0.016192058,-0.057684205,-0.036485393,-0.01487379,-0.03502065,0.36517352,-0.028282838,0.07510132,-0.03241075,0.0017044271,0.0016636474,-0.07057393,0.005775744,-0.04101278,-0.03882898,0.080800496,-0.043356366,0.02308966,-0.0028762207,-0.013628759,-0.008528793,0.031398743,-0.007909607,0.063862756,0.00050267286,-0.033529278,0.010832434,-0.0093943225,0.06998804,-0.018482381,0.096193604,0.011158671,0.081386395,0.09731214,-0.0014148076,0.027696941,0.05677873,-0.00847553,-0.07515458,0.0036318945,-0.0058023757,-0.026631674,-0.0004498256,-0.05392914,0.013795207,-0.060613688,-0.0060320743,-0.084848516,0.041